code='''from collections import Counter, deque

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    bg=Counter(x for row in a for x in row).most_common(1)[0][0]
    seen=set()
    for r in range(h):
        for c in range(w):
            color=a[r][c]
            if color==bg or (r,c) in seen:
                continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and a[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            ih,iw=r1-r0-1,c1-c0-1
            if ih<=0 or iw<=0 or len(cells)!=(r1-r0+1)*2+(c1-c0-1)*2:
                continue
            if any(a[y][x]!=color for y in (r0,r1) for x in range(c0,c1+1)) or any(a[y][x]!=color for x in (c0,c1) for y in range(r0,r1+1)):
                continue
            if any(a[y][x]!=bg for y in range(r0+1,r1) for x in range(c0+1,c1)):
                continue
            fill=2 if ih%2==0 and iw%2==0 else 7
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    a[y][x]=fill
    return a
'''
